  // ambient derivatives already computed at this exact physical point. Keep
  // a previously computed superset and its resident buffers. The complete
  // source/parameter byte keys still invalidate every changed physical state.
  const bool computed=std::any_of(batches.begin(),batches.end(),[](const Batch&b){return b.jacobian_ready;});
